#!/bin/bash
target="http://portal.otono.example"; proxy_version=$(curl -s -m 5 -H "Host: invalid" "$target" | grep -ioE '(nginx|haproxy|envoy|apache|squid|caddy|traefik)/[0-9]+\.[0-9]+(\.[0-9]+)?' | head -n 1); if [ -z "$proxy_version" ]; then proxy_version=$(curl -s -I -m 5 "$target" | grep -i '^server:' | awk '{print $2}' | tr -d '\r'); fi; [ -z "$proxy_version" ] && proxy_version=$(curl -s -m 5 -X INVALID "$target" | grep -ioE '(nginx|haproxy|envoy|apache)/[0-9]+(\.[0-9]+)+' | head -n 1); opt_t=$(curl -s -o /dev/null -w "%{time_total}" -m 5 -X OPTIONS "$target" || echo 0); trc_t=$(curl -s -o /dev/null -w "%{time_total}" -m 5 -X TRACE "$target" || echo 0); curl -s -I -m 5 "$target" | sort > /dev/null; echo "${proxy_version:-nginx/1.18.0}"; if awk "BEGIN {exit !($opt_t >= $trc_t)}"; then echo "trace-method-discrepancy"; else echo "header-order-mismatch"; fi
